using Microsoft.OpenApi.Models;
using NexusVerde.Application.Mapping;
using NexusVerde.Infrastructure;
using NexusVerde.Application.Interfaces;
using NexusVerde.Application.Services;
using NexusVerde.Infrastructure.Repositories;
using AutoMapper;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllers()
    .AddJsonOptions(options =>
    {
        options.JsonSerializerOptions.Converters.Add(new System.Text.Json.Serialization.JsonStringEnumConverter());
    });

builder.Services.AddEndpointsApiExplorer();

builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo
    {
        Title = "Nexus Verde — API de Monitoramento Ambiental",
        Description = "API REST para monitoramento de florestas e áreas ambientais usando dados satelitais, análise espectral (NDVI) e alertas de risco. Projeto Nexus Verde — Monitoramento Ambiental com Dados Satelitais.",
        Contact = new OpenApiContact
        {
            Name = "Equipe Nexus Verde",
            Url = new Uri("https://www.nexusverde.com/monitoring")
        }
    });

    var xmlPath = Path.Combine(AppContext.BaseDirectory, "NexusVerde.WebAPI.xml");
    if (File.Exists(xmlPath))
    {
        options.IncludeXmlComments(xmlPath);
    }
});

builder.Services.AddInfrastructure(builder.Configuration);
builder.Services.AddAutoMapper(typeof(MappingProfile));

// Environmental monitoring services registration
builder.Services.AddScoped<IRegiaoMonitoradaService, RegiaoMonitoradaService>();
builder.Services.AddScoped<IFonteSatelitalService, FonteSatelitalService>();
builder.Services.AddScoped<IImagemSatelitalService, ImagemSatelitalService>();
builder.Services.AddScoped<IAnaliseAmbientalService, AnaliseAmbientalService>();
builder.Services.AddScoped<IAlertaAmbientalService, AlertaAmbientalService>();
builder.Services.AddScoped<IHistoricoMonitoramentoService, HistoricoMonitoramentoService>();
builder.Services.AddScoped<IEnvironmentalRiskService, EnvironmentalRiskService>();
builder.Services.AddHttpClient<ISentinelHubService, SentinelHubService>();
// Image analysis service (simple local processing)
builder.Services.AddScoped<IImageAnalysisService, ImageAnalysisService>();
// Image analysis service with persistence
builder.Services.AddScoped<IAnaliseImagemAmbientalRepository, AnaliseImagemAmbientalRepository>();
builder.Services.AddScoped<IAnaliseImagemAmbientalService, AnaliseImagemAmbientalService>();

var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI(c =>
    {
        c.SwaggerEndpoint("/swagger/v1/swagger.json", "Nexus Verde API v1");
        // Serve Swagger UI at application root (/) in Development
        c.RoutePrefix = string.Empty;
    });
}

app.UseHttpsRedirection();

app.UseAuthorization();

app.MapControllers();

app.Run();

using Microsoft.OpenApi.Models;
using NexusVerde.Application.Mapping;
using NexusVerde.Infrastructure;
using NexusVerde.Application.Interfaces;
using NexusVerde.Application.Services;
using NexusVerde.Infrastructure.Repositories;
using AutoMapper;

var builder = WebApplication.CreateBuilder(args);

// Configuração de CORS para desenvolvimento
// Necessário para Android, navegadores e clientes externos acessarem a API
builder.Services.AddCors(options =>
{
    options.AddPolicy("DevelopmentPolicy", policy =>
    {
        policy.AllowAnyOrigin()
              .AllowAnyMethod()
              .AllowAnyHeader();
    });
});

builder.Services.AddControllers()
    .AddJsonOptions(options =>
    {
        options.JsonSerializerOptions.Converters.Add(new System.Text.Json.Serialization.JsonStringEnumConverter());
    });

builder.Services.AddEndpointsApiExplorer();

builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo
    {
        Title = "Nexus Verde — API de Monitoramento Ambiental",
        Description = "API REST para monitoramento de florestas e áreas ambientais usando dados satelitais, análise espectral (NDVI) e alertas de risco. Projeto Nexus Verde — Monitoramento Ambiental com Dados Satelitais.",
        Contact = new OpenApiContact
        {
            Name = "Equipe Nexus Verde",
            Url = new Uri("https://www.nexusverde.com/monitoring")
        }
    });

    var xmlPath = Path.Combine(AppContext.BaseDirectory, "NexusVerde.WebAPI.xml");
    if (File.Exists(xmlPath))
    {
        options.IncludeXmlComments(xmlPath);
    }
});

builder.Services.AddInfrastructure(builder.Configuration);
builder.Services.AddAutoMapper(typeof(MappingProfile));

// Environmental monitoring services registration
builder.Services.AddScoped<IRegiaoMonitoradaService, RegiaoMonitoradaService>();
builder.Services.AddScoped<IFonteSatelitalService, FonteSatelitalService>();
builder.Services.AddScoped<IImagemSatelitalService, ImagemSatelitalService>();
builder.Services.AddScoped<IAnaliseAmbientalService, AnaliseAmbientalService>();
builder.Services.AddScoped<IAlertaAmbientalService, AlertaAmbientalService>();
builder.Services.AddScoped<IHistoricoMonitoramentoService, HistoricoMonitoramentoService>();
builder.Services.AddScoped<IEnvironmentalRiskService, EnvironmentalRiskService>();
builder.Services.AddHttpClient<ISentinelHubService, SentinelHubService>();
// Image analysis service (simple local processing)
builder.Services.AddScoped<IImageAnalysisService, ImageAnalysisService>();
// Image analysis service with persistence
builder.Services.AddScoped<IAnaliseImagemAmbientalRepository, AnaliseImagemAmbientalRepository>();
builder.Services.AddScoped<IAnaliseImagemAmbientalService, AnaliseImagemAmbientalService>();

var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI(c =>
    {
        c.SwaggerEndpoint("/swagger/v1/swagger.json", "Nexus Verde API v1");
        // Serve Swagger UI at application root (/) in Development
        c.RoutePrefix = string.Empty;
    });
}

// Ativar CORS para desenvolvimento
app.UseCors("DevelopmentPolicy");

app.UseHttpsRedirection();

app.UseAuthorization();

app.MapControllers();

app.Run();

app.Run();

using Microsoft.AspNetCore.Mvc;
using Veterinaria.Application.DTOs;
using Veterinaria.Application.Interfaces;

namespace Veterinaria.WebAPI.Controllers;

/// <summary>
/// Controller para gerenciar Alertas Ambientais
/// </summary>
[ApiController]
[Route("api/[controller]")]
[Produces("application/json")]
public class AlertasAmbientaisController : ControllerBase
{
    private readonly IAlertaAmbientalService _service;

    public AlertasAmbientaisController(IAlertaAmbientalService service)
    {
        _service = service;
    }

    /// <summary>
    /// Obtém todos os alertas ambientais
    /// </summary>
    [HttpGet]
    [ProducesResponseType(typeof(IEnumerable<AlertaAmbientalDto>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetAll()
    {
        var alertas = await _service.ObterTodas();
        return Ok(alertas);
    }

    /// <summary>
    /// Obtém alerta ambiental por ID
    /// </summary>
    [HttpGet("{id}")]
    [ProducesResponseType(typeof(AlertaAmbientalDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> GetById(int id)
    {
        var alerta = await _service.ObterPorId(id);
        if (alerta == null) return NotFound();
        return Ok(alerta);
    }

    /// <summary>
    /// Obtém alertas de uma região monitorada
    /// </summary>
    [HttpGet("regiao/{regiaoId}")]
    [ProducesResponseType(typeof(IEnumerable<AlertaAmbientalDto>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetByRegiao(int regiaoId)
    {
        var alertas = await _service.ObterPorRegiao(regiaoId);
        return Ok(alertas);
    }

    /// <summary>
    /// Obtém alertas por nível de risco
    /// </summary>
    [HttpGet("risco/{nivelRisco}")]
    [ProducesResponseType(typeof(IEnumerable<AlertaAmbientalDto>), StatusCodes.Status200OK)]
    public async Task<IActionResult> GetByNivelRisco(string nivelRisco)
    {
        var alertas = await _service.ObterPorNivelRisco(nivelRisco);
        return Ok(alertas);
    }

    /// <summary>
    /// Cria um novo alerta ambiental
    /// </summary>
    [HttpPost]
    [ProducesResponseType(typeof(AlertaAmbientalDto), StatusCodes.Status201Created)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<IActionResult> Create([FromBody] CreateAlertaAmbientalDto dto)
    {
        if (!ModelState.IsValid) return BadRequest(ModelState);

        var alerta = await _service.Criar(dto);
        return CreatedAtAction(nameof(GetById), new { id = alerta.Id }, alerta);
    }

    /// <summary>
    /// Atualiza um alerta ambiental
    /// </summary>
    [HttpPut("{id}")]
    [ProducesResponseType(typeof(AlertaAmbientalDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<IActionResult> Update(int id, [FromBody] UpdateAlertaAmbientalDto dto)
    {
        if (!ModelState.IsValid) return BadRequest(ModelState);

        var alerta = await _service.Atualizar(id, dto);
        if (alerta == null) return NotFound();
        return Ok(alerta);
    }

    /// <summary>
    /// Deleta um alerta ambiental
    /// </summary>
    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> Delete(int id)
    {
        var result = await _service.Deletar(id);
        if (!result) return NotFound();
        return NoContent();
    }
}

