namespace Veterinaria.Application.Mapping;

public class MappingProfile : Profile
{
    public MappingProfile()
    {
        // Pet mappings
        CreateMap<Pet, PetDto>();
        CreateMap<CreatePetDto, Pet>()
            .ForMember(d => d.CreatedAt, opt => opt.MapFrom(_ => DateTime.UtcNow));
        CreateMap<UpdatePetDto, Pet>();
        // Tutor mappings
        CreateMap<Tutor, TutorDto>();
        CreateMap<CreateTutorDto, Tutor>();
        CreateMap<UpdateTutorDto, Tutor>();
        CreateMap<UpdateTutorDto, Tutor>();

        // Vacina mappings
        CreateMap<Vacina, VacinaDto>();
        CreateMap<CreateVacinaDto, Vacina>();
        CreateMap<UpdateVacinaDto, Vacina>();

        // Consulta mappings
        // Consulta mappings
        CreateMap<Consulta, ConsultaDto>();
        CreateMap<CreateConsultaDto, Consulta>();
        // Medicamento mappings
        CreateMap<Medicamento, MedicamentoDto>();
        CreateMap<CreateMedicamentoDto, Medicamento>();
        CreateMap<CreateMedicamentoDto, Medicamento>();

        // Alerta mappings
        CreateMap<Alerta, AlertaDto>();
        CreateMap<AlertaDto, Alerta>();
        CreateMap<UpdateAlertaDto, Alerta>();
        CreateMap<UpdateAlertaDto, Alerta>();
    }
}

